const fixing = atom({ plugin: 'pr-watch', key: 'fixing' } as const, {})
const addressing = atom({ plugin: 'pr-watch', key: 'addressing' } as const, {})
const resolving = atom({ plugin: 'pr-watch', key: 'resolving' } as const, {})
