const FRAME_MS = 90

// Module memory: lost on reload, which only costs one extra poll.
let isTicking = false
let hasHinted = false
// What the pane last drew, so the animation can blit frames of the same size: a stacked card's
// CI bar width, and a banner card as laid out (art.ts).
