const sixteen = (n: number): ToneLook => ({ ink: `ansi256(${n})`, border: `ansi256(${n})`, fill: null, glow: null })
const SIXTEEN: Record<Tone, ToneLook> = {
  success: sixteen(2),
  error: sixteen(1),
  warning: sixteen(3),
  merged: sixteen(5),
  subtle: sixteen(8),
  suggestion: sixteen(6),
}

